{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO no-fault eviction relocation assistance","requirement":"For a no-fault eviction of an RSO unit, the landlord must file a Declaration of Intent to Evict with LAHD before serving notice, file a copy of the notice within 3 days, and pay relocation assistance within 15 days of service.","key_value":"$11,000–$27,400 per unit (July 1, 2026–June 30, 2027)","coverage_conditions":"Units covered by the Los Angeles Rent Stabilization Ordinance; not-at-fault evictions for owner or relative occupancy, demolition or withdrawal from rental use, order to vacate, HUD sale, residential hotel conversion or condominium conversion.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Rental units covered by the RSO"},"exemptions":"Replacing a resident manager; eviction required by hazardous conditions from a natural disaster not caused by landlord negligence; a landlord may offset unpaid rent against relocation assistance except where a governmental order to vacate applies.","penalty":"Failure to file the Landlord Declaration with LAHD makes the eviction a violation of the RSO; a tenant may raise non-payment of relocation assistance as an affirmative defense in the eviction action.","effective_date":"2026-07-01","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"JCO no-fault eviction relocation assistance","requirement":"For a no-fault eviction of a JCO unit, the landlord must file a Declaration of Intent to Evict with LAHD and pay relocation assistance; a JCO single-family dwelling owned by a natural person with no more than four units owes one month's rent.","key_value":"$11,000–$27,400 per unit (July 1, 2026–June 30, 2027)","coverage_conditions":"Units covered by the Los Angeles Just Cause Ordinance, including not-at-fault evictions for owner or relative occupancy, demolition, order to vacate, HUD sale, hotel conversion or condominium conversion.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Rental units covered by the JCO"},"exemptions":"Replacing a resident manager; eviction required by hazardous conditions from a natural disaster not caused by landlord negligence; a landlord may offset unpaid rent against relocation assistance except where a governmental order to vacate applies.","penalty":"Failure to file the Landlord Declaration with LAHD makes the eviction a violation of the JCO; a tenant may raise non-payment of relocation assistance as an affirmative defense in the eviction action.","effective_date":"2026-07-01","citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"one month’s rent that was in effect when the landlord served the written notice to terminate the tenancy, as either a monetary payment or credit.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Resident Protections Ordinance demolition relocation and occupant protections","requirement":"An owner demolishing a Protected Unit for new construction within five years of filing a notice with LAHD must comply with RPO relocation requirements and pay the highest of the state and city relocation amounts, which are enhanced for lower income tenants.","key_value":"$250,000 per displaced unit","coverage_conditions":"Applies only to Protected Units demolished for new construction: units under affordable-housing covenants, rent or price control (including all RSO units) within five years, lower income households, or Ellis Act withdrawals within ten years.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Protected Units demolished for new construction"},"exemptions":"Regular RSO or JCO relocation rules apply where the units to be demolished are not Protected Units or are not occupied by a lower income tenant.","penalty":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","citation":"Resident Protections Ordinance (Ordinances #188481 and #188482)","quoted_span":"Owners who demolish a Protected Unit for the purpose of new construction within 5 years after the filing of the Notice of Intent to Withdraw or Declaration of Intent to Evict with LAHD are required to comply with relocation requirements under the RPO.","interaction":"Relocation must be the higher of state Housing Crisis Act or city amounts; RSO or JCO amounts must be enhanced for lower income tenants under the HCA.","confidence":0.75,"conflict_flag":false,"conflict_note":null}
